   100→            'pertemuan_ke'    => 'required|integer|min:1',
   101→            'tanggal'         => 'required|date',
   102→            'tanggal_selesai' => 'nullable|date|after_or_equal:tanggal',
   103→            'jam_mulai'       => 'required',
   104→            'jam_selesai'     => 'required',
   105→            'topik'           => 'nullable|string|max:200',
   106→            'ruangan'         => 'nullable|string|max:100',
   107→            'link_meeting'    => 'nullable|url|max:500',
   108→            'catatan'         => 'nullable|string',
   109→        ]);
   110→
   111→        $paket = Package::with('cabang')->findOrFail($data['paket_id']);
   112→
   113→        if ($data['pertemuan_ke'] > $paket->jumlah_pertemuan) {
   114→            $msg = "Sesi ke-{$data['pertemuan_ke']} melebihi jumlah sesi paket ({$paket->jumlah_pertemuan}).";
   115→            if ($request->wantsJson() || $request->ajax()) {
   116→                return response()->json(['success' => false, 'message' => $msg], 422);
   117→            }
   118→            return back()->withErrors(['pertemuan_ke' => $msg])->withInput();
   119→        }
   120→
   121→        // Cegah duplikat sesi pada paket yang sama
   122→        $sudahAda = Schedule::where('paket_id', $data['paket_id'])
   123→            ->where('pertemuan_ke', $data['pertemuan_ke'])
   124→            ->whereNull('deleted_at')
   125→            ->exists();
   126→        if ($sudahAda) {
   127→            $msg = "Sesi ke-{$data['pertemuan_ke']} untuk paket ini sudah pernah dijadwalkan.";
   128→            if ($request->wantsJson() || $request->ajax()) {
   129→                return response()->json(['success' => false, 'message' => $msg], 422);
   130→            }
   131→            return back()->withErrors(['pertemuan_ke' => $msg])->withInput();
   132→        }
   133→
   134→        // Use form guru_id if provided, otherwise fall back to package's guru
   135→        $data['guru_id']   = $data['guru_id'] ?? $paket->guru_id;
   136→        $data['cabang_id'] = $paket->cabang_id;
   137→        // $data['jenis'] comes from the form (online/offline/private)
   138→        $data['status']    = 'dijadwalkan';
   139→
   140→        $schedule = Schedule::create($data);
   141→        $schedule->load(['paket.guru', 'paket.mataPelajaran']);
   142→
   143→        if ($request->wantsJson() || $request->ajax()) {
   144→            return response()->json(['success' => true, 'message' => 'Jadwal sesi berhasil ditambahkan.', 'data' => $schedule]);
   145→        }
   146→        return redirect()->route('admin.schedules.create')->with('success', 'Jadwal sesi berhasil ditambahkan!');
   147→    }
